// Decodificar base64 a binary y preparar para Gemini

const base64Data = $input.first().json.pdf_base64;
const filename = $input.first().json.filename;
const apiKey = $input.first().json.api_key;
const tipoRubrica = $input.first().json.tipo_rubrica;

if (!base64Data || !apiKey) {
  throw new Error("Faltan datos requeridos: pdf_base64 y api_key");
}

// Decodificar base64
const buffer = Buffer.from(base64Data, 'base64');

// Preparar para siguiente nodo
return [{
  json: {
    api_key: apiKey,
    tipo_rubrica: tipoRubrica,
    filename: filename
  },
  binary: {
    pdf: {
      data: buffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: filename || 'documento.pdf'
    }
  }
}];

// Construir body para Gemini con el PDF subido y el prompt de generación de rúbrica V2

const uploadResponse = $input.first().json;
const apiKey = $('Decodificar PDF').first().json.api_key;

// Verificar si hubo error en upload
if (uploadResponse.error) {
  throw new Error(`Error al subir PDF a Gemini: ${JSON.stringify(uploadResponse.error)}`);
}

const fileUri = uploadResponse.file?.uri;
if (!fileUri) {
  throw new Error("No se obtuvo URI del archivo subido");
}

// Prompt actualizado para generar esquema de rúbrica V2
const prompt = `# Rol del sistema
Sos un asistente experto en evaluación académica que convierte instrucciones de trabajos prácticos y exámenes (en PDF) en rúbricas JSON estandarizadas, completas y verificables.

# Objetivo
A partir del contenido del PDF provisto, generá una rúbrica en JSON que describa con precisión cómo evaluar la entrega del alumno.

**Salida:** un único objeto JSON válido (sin texto adicional, sin comentarios, sin markdown).

# Esquema de salida requerido

Debes generar un JSON con la siguiente estructura:

\`\`\`json
{
  "titulo": "string",
  "descripcion": "string",
  "puntaje_maximo": 100,
  "metadata": {
    "materia": "string",
    "carrera": "string | null",
    "modalidad": "string | null",
    "lenguaje": "string | string[]",
    "framework": "string | null",
    "version": "string | null",
    "formato_entrega": {
      "tipo": "string",
      "extensiones_aceptadas": ["string"],
      "archivo_unico": "boolean | null",
      "publico": "boolean | null",
      "restricciones": ["string"]
    }
  },
  "criterios": [
    {
      "id": "string",
      "nombre": "string",
      "descripcion": "string",
      "peso": "number",
      "instrucciones_puntuacion": "string | null",
      "subcriterios": [
        {
          "id": "string",
          "descripcion": "string",
          "evidencias": ["string"]
        }
      ]
    }
  ],
  "penalizaciones": [
    {
      "id": "string",
      "descripcion": "string",
      "descuento_porcentaje": "number"
    }
  ],
  "condiciones_desaprobacion": [
    {
      "id": "string",
      "condicion": "string",
      "nota_final": "number"
    }
  ]
}
\`\`\`

# Reglas de generación

## 1. Información General
- **titulo**: Extraer del PDF el nombre del TP/parcial/final
- **descripcion**: Resumen breve de qué evalúa (1-2 líneas)
- **puntaje_maximo**: Siempre 100 (fijo)

## 2. Metadata
- Inferir del PDF la información de contexto:
  - **materia**, **carrera**, **modalidad** (presencial/virtual)
  - **lenguaje** (ej: "JavaScript", "Python", o array si son varios)
  - **framework** (ej: "Express.js", "React", "Spring Boot")
  - **version** si se especifica (ej: "Node 18+", "Java 17+")
  - **formato_entrega**: inferir tipo (GitHub/ZIP/etc), extensiones aceptadas, si es público, restricciones
- Si no hay info en el PDF, usar null

## 3. Criterios
- Cada criterio debe tener:
  - **id**: formato "C1", "C2", etc. (únicos)
  - **nombre**: título del criterio
  - **descripcion**: qué evalúa
  - **peso**: porcentaje (número entero, la suma de todos debe ser 100)
  - **instrucciones_puntuacion**: opcional, cómo dividir puntaje entre subcriterios
  - **subcriterios**: array con al menos 1 subcriterio
- Distribución típica de pesos:
  - Funcionalidad: 35-45%
  - Calidad de código/validaciones: 20-30%
  - Documentación: 15-20%
  - Entrega: 10-15%

## 4. Subcriterios
- Cada subcriterio debe tener:
  - **id**: formato "C1.1", "C1.2", etc. (únicos dentro del criterio)
  - **descripcion**: aspecto específico a verificar
  - **evidencias**: array de strings con checks VERIFICABLES por IA
- Evidencias deben ser:
  - ✅ Específicas: "Archivo package.json existe", "Endpoint POST /productos retorna 201"
  - ❌ Evitar ambiguas: "Código de calidad", "Funciona bien"

## 5. Penalizaciones
- Generar penalizaciones comunes:
  - Repositorio inaccesible: 100%
  - Código no ejecuta: 50%
  - Falta README: 20%
  - Entrega fuera de fecha (si se menciona)
- Si el PDF menciona penalizaciones específicas, incluirlas
- Formato:
  - **id**: "P1", "P2", etc.
  - **descripcion**: qué la activa
  - **descuento_porcentaje**: 0-100

## 6. Condiciones de Desaprobación
- Generar al menos 2:
  - Plagio detectado: nota_final 0
  - No implementa X requisitos mínimos: nota_final 30
- Si el PDF menciona condiciones específicas, incluirlas
- Formato:
  - **id**: "CD1", "CD2", etc.
  - **condicion**: qué la activa
  - **nota_final**: 0-100

# Validaciones críticas
- ✅ La suma de "peso" de todos los criterios debe ser exactamente 100
- ✅ Todos los IDs (criterios, subcriterios, penalizaciones, condiciones) deben ser únicos
- ✅ Cada subcriterio debe tener al menos 1 evidencia
- ✅ descuento_porcentaje y nota_final deben estar entre 0 y 100
- ✅ metadata es flexible pero debe tener al menos "materia"

# Instrucciones finales
- Lee completamente el PDF
- Extrae todas las consignas, tecnologías mencionadas, requisitos, puntajes
- Genera el JSON siguiendo el esquema exacto
- Verifica que la suma de pesos sea 100
- Devuelve SOLO el JSON, sin texto adicional, sin markdown, sin comentarios`;

// Construir body para Gemini generateContent
const body = {
  generationConfig: {
    temperature: 0.3,
    topK: 40,
    topP: 0.95,
    responseMimeType: "text/plain"
  },
  contents: [
    {
      role: "user",
      parts: [
        {
          fileData: {
            fileUri: fileUri,
            mimeType: "application/pdf"
          }
        },
        {
          text: prompt
        }
      ]
    }
  ]
};

return [
  {
    json: {
      geminiBody: body,
      api_key: apiKey
    }
  }
];

// Extraer JSON de la respuesta (quitar ```json...```)

const geminiResponse = $input.first().json;

try {
  // Verificar errores de Gemini
  if (geminiResponse.error) {
    const errorMsg = geminiResponse.error.message || JSON.stringify(geminiResponse.error);
    const errorCode = geminiResponse.error.code || 'UNKNOWN';

    return [{ 
      json: { 
        success: false,
        error: {
          code: "GEMINI_ERROR",
          message: `Error de Gemini [${errorCode}]: ${errorMsg}`,
          retry: errorCode === 503 || errorCode === 500
        }
      } 
    }];
  }

  // Normalizar respuesta
  let responseArray;
  if (Array.isArray(geminiResponse)) {
    responseArray = geminiResponse;
  } else if (geminiResponse.body && Array.isArray(geminiResponse.body)) {
    responseArray = geminiResponse.body;
  } else {
    responseArray = [geminiResponse];
  }

  const candidate = responseArray[0]?.candidates?.[0];
  if (!candidate) {
    return [{ 
      json: { 
        success: false,
        error: {
          code: "PARSING_ERROR",
          message: "No se encontró candidate en respuesta",
          retry: true
        }
      } 
    }];
  }

  const textContent = candidate.content?.parts?.[0]?.text;
  if (!textContent) {
    return [{ 
      json: { 
        success: false,
        error: {
          code: "PARSING_ERROR",
          message: "No se encontró texto en respuesta",
          retry: true
        }
      } 
    }];
  }

  // Extraer JSON (puede venir envuelto en ```json...```)
  let jsonText = textContent;
  const match = textContent.match(/```json\s*([\s\S]*?)```/i) || textContent.match(/```\s*([\s\S]*?)```/);
  if (match) {
    jsonText = match[1].trim();
  }

  // Parsear JSON
  const rubricaCompleta = JSON.parse(jsonText);

  // Pasar al siguiente nodo para mapeo
  return [{ json: { rubricaCompleta } }];

} catch (error) {
  return [{ 
    json: { 
      success: false,
      error: {
        code: "PARSING_ERROR",
        message: `Error al parsear JSON: ${error.message}`,
        retry: false
      }
    } 
  }];
}

// Validar esquema V2 generado por Gemini

const data = $input.first().json;

// Si hay error, pasarlo directamente
if (data.error) {
  return [{ json: data }];
}

const rubricaV2 = data.rubricaCompleta;

// Validaciones básicas de estructura V2
if (!rubricaV2) {
  return [{ 
    json: { 
      success: false,
      error: {
        code: "VALIDATION_ERROR",
        message: "Rúbrica vacía o inválida",
        retry: false
      }
    } 
  }];
}

if (!rubricaV2.titulo || !rubricaV2.descripcion) {
  return [{ 
    json: { 
      success: false,
      error: {
        code: "VALIDATION_ERROR",
        message: "Faltan campos requeridos: titulo o descripcion",
        retry: false
      }
    } 
  }];
}

if (!rubricaV2.criterios || rubricaV2.criterios.length === 0) {
  return [{ 
    json: { 
      success: false,
      error: {
        code: "VALIDATION_ERROR",
        message: "La rúbrica debe tener al menos un criterio",
        retry: false
      }
    } 
  }];
}

// Validar suma de pesos = 100
const sumaPesos = rubricaV2.criterios.reduce((sum, c) => sum + (c.peso || 0), 0);
if (Math.abs(sumaPesos - 100) > 1) {
  // Intentar ajustar automáticamente
  const diferencia = 100 - sumaPesos;
  rubricaV2.criterios[rubricaV2.criterios.length - 1].peso += diferencia;

  console.log(`Suma de pesos ajustada de ${sumaPesos} a 100`);
}

// Validar IDs únicos en criterios
const criterioIds = rubricaV2.criterios.map(c => c.id);
const criterioIdsUnicos = new Set(criterioIds);
if (criterioIds.length !== criterioIdsUnicos.size) {
  return [{ 
    json: { 
      success: false,
      error: {
        code: "VALIDATION_ERROR",
        message: "IDs de criterios duplicados",
        retry: false
      }
    } 
  }];
}

// Validar subcriterios y evidencias
for (const criterio of rubricaV2.criterios) {
  if (!criterio.subcriterios || criterio.subcriterios.length === 0) {
    return [{ 
      json: { 
        success: false,
        error: {
          code: "VALIDATION_ERROR",
          message: `Criterio ${criterio.id} no tiene subcriterios`,
          retry: false
        }
      } 
    }];
  }

  for (const sub of criterio.subcriterios) {
    if (!sub.evidencias || sub.evidencias.length === 0) {
      return [{ 
        json: { 
          success: false,
          error: {
            code: "VALIDATION_ERROR",
            message: `Subcriterio ${sub.id} no tiene evidencias`,
            retry: false
          }
        } 
      }];
    }
  }
}

// Validar descuentos de penalizaciones (0-100)
if (rubricaV2.penalizaciones) {
  for (const p of rubricaV2.penalizaciones) {
    if (p.descuento_porcentaje < 0 || p.descuento_porcentaje > 100) {
      return [{ 
        json: { 
          success: false,
          error: {
            code: "VALIDATION_ERROR",
            message: `Penalización ${p.id} tiene descuento inválido: ${p.descuento_porcentaje}`,
            retry: false
          }
        } 
      }];
    }
  }
}

// Construir respuesta exitosa
const respuesta = {
  success: true,
  rubrica: rubricaV2,
  metadata: {
    generated_at: new Date().toISOString(),
    schema_version: "v2",
    total_criterios: rubricaV2.criterios.length,
    total_penalizaciones: rubricaV2.penalizaciones?.length || 0,
    total_condiciones: rubricaV2.condiciones_desaprobacion?.length || 0
  }
};

return [{ json: respuesta }];
